package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.AsOfAllowed;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.session.CurrentUser;
import net.officefloor.hq.app.settings.SettingsController.DatedValue;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.settings.ViewerAllowed;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** A sheet as the screen takes it: its id, its today, its floor with two decimals, its
     *  terms in days, its late percent with two decimals, its policy date (null when blank), and its cap with two decimals (null when none),
     *  the dated ones as in force on its today; and every value recorded for its dated settings,
     *  by key, each key's by from-date; and whether it is archived. */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct, LocalDate policyDate,
            String cap, Map<String, List<DatedValue>> dated, boolean archived) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().setScale(2).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().setScale(2).toPlainString(),
                    DatedValue.of(sheet.getDatedSettings()), sheet.isArchived());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;
    private final SettingsService settings;
    private final HistoryService history;

    public SheetController(SheetService service, SettingsService settings, HistoryService history) {
        this.service = service;
        this.settings = settings;
        this.history = history;
    }

    /** Load the sheet; shown as of a date, it is as it stood at the end of that date, that date its today. */
    @PostMapping("/{id}/load")
    @ViewerAllowed
    @AsOfAllowed
    public SheetView load(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        Sheet sheet = service.load(id, user.trim());
        return SheetView.of(asOf == null ? sheet : history.asOf(id, asOf).sheet());
    }

    @PutMapping("/{id}/today")
    public SheetView setToday(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TodayChange body) {
        return SheetView.of(service.setToday(id, user.trim(), body.today()));
    }

    /** Archive the sheet: a steward only; everything stays visible and every change is refused. */
    @PostMapping("/{id}/archive")
    public SheetView archive(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return SheetView.of(settings.archive(id, user.trim()));
    }
}
import { Component, computed, inject, input } from '@angular/core';
import { Session } from '../../core/session';
import { Claim, money } from '../claims/claims-api';
import { GRADES } from '../people/people-api';
import { Period, periodDueCents } from '../periods/periods-api';

/** The statuses the summary counts, in the order it lists them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/** How many of the claims have each status, in the order the summary lists them. */
export function statusCounts(claims: Claim[]): { status: string; count: number }[] {
  return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === (status as string)).length }));
}

/** A person as the summary counts them: their grade in force on the sheet's today, whether they
 *  are retired, their due-total in cents (null: n/a), and whether they are active. */
export interface SummaryPerson {
  grade: string;
  retired: boolean;
  due: number | null;
  active: boolean;
}

// The sheet in figures, each as the lists show it: per grade, how many people not retired are on it
// today, their due-totals added up (n/a skipped) and how many of them are active; per period, its due-total; per status, how
// many claims have it; per void reason on the sheet's list, how many VOID claims were voided with it.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <table data-testid="summary-grades">
        <caption>By grade</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due</th><th scope="col">Active</th></tr>
        </thead>
        <tbody>
          @for (g of byGrade(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ money(g.cents) }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <caption>By period</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due</th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.id) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ money(periodDue(p)) }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <caption>By status</caption>
        <thead>
          <tr><th scope="col">Status</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (s of byStatus(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="summary-void-reasons">
        <caption>Voided by reason</caption>
        <thead>
          <tr><th scope="col">Reason</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (r of byVoidReason(); track r.reason) {
            <tr>
              <th scope="row">{{ r.reason }}</th>
              <td [attr.data-testid]="'summary-void-' + r.reason + '-count'">{{ r.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Summary {
  readonly people = input.required<SummaryPerson[]>();
  readonly claims = input.required<Claim[]>();
  readonly periods = input.required<Period[]>();
  /** Each open period's live due-total in cents, by period id. */
  readonly dueTotals = input.required<Map<number, number>>();

  protected readonly money = money;

  protected readonly byGrade = computed(() => GRADES.map((grade) => {
    const on = this.people().filter((p) => !p.retired && p.grade === grade);
    return { grade, count: on.length, cents: on.reduce((sum, p) => sum + (p.due ?? 0), 0),
      active: on.filter((p) => p.active).length };
  }));

  private readonly session = inject(Session);

  protected readonly byStatus = computed(() => statusCounts(this.claims()));

  protected readonly byVoidReason = computed(() => this.session.voidReasons().map((reason) => ({
    reason, count: this.claims().filter((c) => c.status === 'VOID' && c.voidReason === reason).length,
  })));

  protected periodDue(p: Period): number {
    return periodDueCents(p, this.dueTotals());
  }
}
import { Component, inject, signal } from '@angular/core';
